# ----------------------------- utility/config -----------------------------

def eprint(*args: Any, **kwargs: Any) -> None:
    print(*args, file=sys.stderr, **kwargs)


def deep_copy(x: Any) -> Any:
    return json.loads(json.dumps(x))


def normalize_key(k: str) -> str:
    return k.replace("_", "-")


def normalize_rule_id(s: str) -> Optional[str]:
    if not s:
        return None
    key = s.strip().strip('"\'').lower()
    return NAME_TO_CODE.get(key)


def split_rules(s: str) -> List[str]:
    parts = re.split(r"[,\s]+", s.strip()) if s else []
    out: List[str] = []
    for p in parts:
        c = normalize_rule_id(p)
        if c and c not in out:
            out.append(c)
    return out


def split_patterns(s: str) -> List[str]:
    if not s:
        return []
    return [p.strip() for p in s.split(",") if p.strip()]


def merge_dict(dst: Dict[str, Any], src: Dict[str, Any]) -> None:
    for k, v in src.items():
        nk = normalize_key(k)
        if isinstance(v, dict) and isinstance(dst.get(nk), dict):
            merge_dict(dst[nk], v)
        else:
            dst[nk] = v


def read_toml(path: Path) -> Dict[str, Any]:
    if tomllib is None:
        return {}
    with open(path, "rb") as f:
        return tomllib.load(f)


def find_config(start: Path) -> Optional[Path]:
    cur = start.resolve() if start.exists() else Path.cwd().resolve()
    if cur.is_file():
        cur = cur.parent
    while True:
        for name in (".rumdl.toml", "rumdl.toml", "pyproject.toml"):
            p = cur / name
            if p.exists():
                if name == "pyproject.toml":
                    try:
                        data = read_toml(p)
                        if "tool" in data and "rumdl" in data.get("tool", {}):
                            return p
                    except Exception:
                        pass
                else:
                    return p
        if cur.parent == cur:
            return None
        cur = cur.parent


def extract_config_data(raw: Dict[str, Any], is_pyproject: bool) -> Dict[str, Any]:
    cfg: Dict[str, Any] = {}
    if is_pyproject:
        raw = raw.get("tool", {}).get("rumdl", {}) if isinstance(raw.get("tool"), dict) else {}
        # [tool.rumdl] can contain global keys directly, while [tool.rumdl.global]
        # is also accepted.  Rule tables are nested under MD###.
        global_keys = {"enable", "disable", "exclude", "include", "respect-gitignore", "respect_gitignore", "line-length", "line_length", "flavor", "force-exclude", "force_exclude", "cache", "output-format", "output_format"}
        g: Dict[str, Any] = {}
        for k, v in raw.items():
            if k in ("global", "per-file-ignores", "per-file-flavor", "code-block-tools") or re.fullmatch(r"MD\d{3}", str(k), re.I):
                continue
            if k in global_keys:
                g[normalize_key(k)] = v
        if g:
            cfg["global"] = g
        for k, v in raw.items():
            nk = normalize_key(str(k))
            if nk.lower() == "global" and isinstance(v, dict):
                cfg.setdefault("global", {})
                merge_dict(cfg["global"], v)
            elif nk in ("per-file-ignores", "per-file-flavor", "code-block-tools"):
                cfg[nk] = v
            elif re.fullmatch(r"MD\d{3}", str(k), re.I) and isinstance(v, dict):
                cfg[str(k).upper()] = {normalize_key(kk): vv for kk, vv in v.items()}
    else:
        for k, v in raw.items():
            nk = normalize_key(str(k))
            if re.fullmatch(r"MD\d{3}", str(k), re.I) and isinstance(v, dict):
                cfg[str(k).upper()] = {normalize_key(kk): vv for kk, vv in v.items()}
            elif isinstance(v, dict):
                cfg[nk] = {normalize_key(kk): vv for kk, vv in v.items()}
            else:
                cfg[nk] = v
    return cfg


@dataclass
class LoadedConfig:
    data: Dict[str, Any]
    path: Optional[Path] = None
    source: str = "default"
    changed: Set[str] = field(default_factory=set)


def load_config(config_path: Optional[str] = None, no_config: bool = False) -> LoadedConfig:
    cfg = deep_copy(DEFAULT_CONFIG)
    if cfg["global"].get("line-length") and "MD013" in cfg:
        cfg["MD013"]["line-length"] = cfg["global"]["line-length"]
    if no_config:
        return LoadedConfig(cfg, None, "default", set())
    p: Optional[Path]
    if config_path:
        p = Path(config_path)
    else:
        p = find_config(Path.cwd())
    changed: Set[str] = set()
    if not p:
        return LoadedConfig(cfg, None, "default", changed)
    try:
        raw = read_toml(p)
        extracted = extract_config_data(raw, p.name == "pyproject.toml")
        for k, v in extracted.items():
            nk = normalize_key(k)
            if isinstance(v, dict) and isinstance(cfg.get(nk), dict):
                before = json.dumps(cfg[nk], sort_keys=True)
                merge_dict(cfg[nk], v)
                if json.dumps(cfg[nk], sort_keys=True) != before:
                    changed.add(nk)
            else:
                cfg[nk] = v
                changed.add(nk)
        # global line length applies to MD013 unless overridden explicitly
        if "global" in extracted and isinstance(extracted.get("global"), dict):
            gl = extracted["global"]
            if ("line-length" in gl or "line_length" in gl) and not ("MD013" in extracted and ("line-length" in extracted.get("MD013", {}) or "line_length" in extracted.get("MD013", {}))):
                cfg.setdefault("MD013", {})["line-length"] = cfg["global"].get("line-length", cfg["MD013"].get("line-length", 80))
        return LoadedConfig(cfg, p.resolve(), "pyproject.toml" if p.name == "pyproject.toml" else "project config", changed)
    except FileNotFoundError:
        raise
    except Exception as ex:
        raise RuntimeError(f"Failed to parse config file {p}: {ex}")


def toml_value(v: Any) -> str:
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, str):
        return json.dumps(v)
    if isinstance(v, list):
        if not v:
            return "[]"
        if all(not isinstance(x, (dict, list)) for x in v):
            return "[" + ", ".join(toml_value(x) for x in v) + "]"
        return json.dumps(v)
    if isinstance(v, dict):
        if not v:
            return "{}"
        return json.dumps(v)
    if v is None:
        return '""'
    return str(v)


def config_to_toml(cfg: Dict[str, Any], only_defaults: bool = False) -> str:
    order = ["global", "per-file-ignores", "per-file-flavor", "code-block-tools"] + [r["code"] for r in RULES if r["code"] in cfg]
    out: List[str] = []
    for section in order:
        if section not in cfg or not isinstance(cfg[section], dict):
            continue
        out.append(f"[{section}]")
        for k, v in cfg[section].items():
            if isinstance(v, dict):
                continue
            out.append(f"{k} = {toml_value(v)}")
        subdicts = [(k, v) for k, v in cfg[section].items() if isinstance(v, dict)]
        out.append("")
        for k, v in subdicts:
            out.append(f"[{section}.{k}]")
            for sk, sv in v.items():
                out.append(f"{sk} = {toml_value(sv)}")
            out.append("")
    return "\n".join(out).rstrip() + "\n"


def get_config_value(cfg: Dict[str, Any], key: str) -> Tuple[Any, str]:
    parts = [normalize_key(p) for p in key.split(".")]
    cur: Any = cfg
    norm_parts: List[str] = []
    for p in parts:
        if isinstance(cur, dict):
            found = None
            for k in cur:
                if normalize_key(str(k)).lower() == p.lower():
                    found = k
                    break
            if found is None:
                return None, ".".join(norm_parts + [p])
            norm_parts.append(str(found))
            cur = cur[found]
        else:
            return None, ".".join(norm_parts)
    return cur, ".".join(norm_parts)


# ----------------------------- document helpers -----------------------------

@dataclass
class Issue:
    file: str
    line: int
    column: int
    rule: str
    message: str
    severity: str = "warning"
    fixable: bool = False
    end_line: Optional[int] = None
    end_column: Optional[int] = None
    fixed: bool = False
    fix: Optional[Dict[str, Any]] = None

    def to_json(self, include_fix: bool = True) -> Dict[str, Any]:
        d: Dict[str, Any] = {
            "file": self.file,
            "line": self.line,
            "column": self.column,
            "rule": self.rule,
            "message": self.message,
            "severity": self.severity,
            "fixable": bool(self.fixable),
        }
        if include_fix:
            d["fix"] = self.fix if self.fixable else None
        return d


def issue(file: str, line: int, column: int, rule: str, message: str, cfg: Dict[str, Any], fixable: Optional[bool] = None, end_col: Optional[int] = None) -> Issue:
    sev = str(cfg.get(rule, {}).get("severity", "error" if rule in ERROR_RULES else "warning"))
    if fixable is None:
        fixable = rule not in NONFIXABLE_DEFAULT
        if rule == "MD013":
            fixable = bool(cfg.get("MD013", {}).get("reflow", False))
        if rule == "MD033":
            fixable = bool(cfg.get("MD033", {}).get("fix", False))
        if rule == "MD036":
            fixable = bool(cfg.get("MD036", {}).get("fix", False))
        if rule == "MD041":
            fixable = bool(cfg.get("MD041", {}).get("fix", False))
    return Issue(file, line, max(1, column), rule, message, sev, bool(fixable), line if end_col else None, end_col)


def split_lines(text: str) -> List[str]:
    if text == "":
        return []
    parts = text.splitlines()
    # str.splitlines drops the final empty string for trailing newline, which is
    # convenient for line-oriented linting.
    return parts


def line_offsets(text: str) -> List[int]:
    offs = []
    pos = 0
    for part in text.splitlines(True):
        offs.append(pos)
        pos += len(part)
    if not offs and text == "":
        offs.append(0)
    return offs


def is_blank(s: str) -> bool:
    return s.strip() == ""


def visual_width(s: str) -> int:
    w = 0
    for ch in s:
        if ch == "\t":
            w += 4
        elif unicodedata.combining(ch):
            continue
        elif unicodedata.east_asian_width(ch) in ("W", "F"):
            w += 2
        elif ord(ch) >= 0x1F300:
            w += 2
        else:
            w += 1
    return w


def leading_spaces(s: str) -> int:
    return len(s) - len(s.lstrip(" "))


def fence_match(line: str) -> Optional[Tuple[str, int, str]]:
    m = re.match(r"^ {0,3}(`{3,}|~{3,})([^`]*)$", line)
    if not m:
        return None
    fence = m.group(1)
    return fence[0], len(fence), m.group(2).strip()


def code_fence_spans(lines: List[str]) -> Tuple[Set[int], List[Tuple[int, int, str, int, str]]]:
    in_code: Set[int] = set()
    spans: List[Tuple[int, int, str, int, str]] = []
    i = 0
    while i < len(lines):
        fm = fence_match(lines[i])
        if not fm:
            i += 1
            continue
        ch, length, info = fm
        start = i
        in_code.add(i + 1)
        i += 1
        while i < len(lines):
            in_code.add(i + 1)
            m2 = re.match(rf"^ {{0,3}}{re.escape(ch)}{{{length},}}\s*$", lines[i])
            if m2:
                spans.append((start + 1, i + 1, ch, length, info))
                i += 1
                break
            i += 1
        else:
            spans.append((start + 1, len(lines), ch, length, info))
    return in_code, spans


def frontmatter_span(lines: List[str]) -> Optional[Tuple[int, int]]:
    if not lines:
        return None
    first = lines[0].strip()
    if first not in ("---", "+++", "{"):
        return None
    if first == "{":
        depth = 0
        for i, line in enumerate(lines, 1):
            depth += line.count("{") - line.count("}")
            if depth <= 0 and i > 1:
                return (1, i)
        return None
    marker = first
    for i in range(2, len(lines) + 1):
        if lines[i - 1].strip() == marker:
            return (1, i)
    return None


def in_span(line_no: int, span: Optional[Tuple[int, int]]) -> bool:
    return bool(span and span[0] <= line_no <= span[1])


def atx_heading(line: str) -> Optional[Tuple[int, str, int, bool]]:
    # Return (level, text, marker_column, closed)
    m = re.match(r"^( {0,3})(#{1,6})(.*)$", line)
    if not m:
        return None
    rest = m.group(3)
    # Must be a heading even if malformed for spacing rules. For well-formed
    # headings, the marker is followed by space or end; for malformed, MD018/019 handles it.
    level = len(m.group(2))
    raw = rest.strip()
    closed = False
    if raw.endswith("#"):
        # Remove closing sequence for heading text.
        raw2 = re.sub(r"\s*#+\s*$", "", raw)
        if raw2 != raw:
            closed = True
            raw = raw2
    return level, raw.strip(), len(m.group(1)) + 1, closed


def setext_heading_at(lines: List[str], idx0: int) -> Optional[Tuple[int, str]]:
    if idx0 <= 0 or idx0 >= len(lines):
        return None
    line = lines[idx0].strip()
    if not re.fullmatch(r"=+|-+", line):
        return None
    prev = lines[idx0 - 1].strip()
    if not prev or atx_heading(lines[idx0 - 1]) or is_list_item(lines[idx0 - 1]):
        return None
    return (1 if line.startswith("=") else 2, prev)


def all_headings(lines: List[str], code_lines: Set[int]) -> List[Tuple[int, int, str, str]]:
    res: List[Tuple[int, int, str, str]] = []
    for i, line in enumerate(lines, 1):
        if i in code_lines:
            continue
        ah = atx_heading(line)
        if ah:
            res.append((i, ah[0], ah[1], "atx_closed" if ah[3] else "atx"))
            continue
        sh = setext_heading_at(lines, i - 1)
        if sh:
            res.append((i - 1, sh[0], sh[1], "setext"))
    res.sort(key=lambda x: x[0])
    return res


def is_list_item(line: str) -> bool:
    return bool(re.match(r"^\s*(?:[-+*]|\d+[.)])\s+", line))


def list_item_match(line: str) -> Optional[re.Match[str]]:
    return re.match(r"^(\s*)(?:(?P<ul>[-+*])|(?P<ol>\d+)(?P<odelim>[.)]))(?P<space>\s*)(?P<rest>.*)$", line)


def is_hr(line: str) -> bool:
    s = line.strip()
    if len(s) < 3:
        return False
    chars = [c for c in s if c != " "]
    return len(chars) >= 3 and len(set(chars)) == 1 and chars[0] in "-*_"


def hr_style(line: str) -> str:
    s = line.strip()
    chars = [c for c in s if c != " "]
    return chars[0] * 3 if chars else s


def is_table_separator(line: str) -> bool:
    s = line.strip()
    if "|" not in s:
        return False
    cells = [c.strip() for c in s.strip("|").split("|")]
    if len(cells) < 2:
        return False
    return all(re.fullmatch(r":?-{3,}:?", c or "") for c in cells)


def is_table_line(lines: List[str], idx0: int) -> bool:
    line = lines[idx0]
    if "|" not in line or is_blank(line):
        return False
    if idx0 + 1 < len(lines) and is_table_separator(lines[idx0 + 1]):
        return True
    if idx0 > 0 and is_table_separator(lines[idx0]):
        return True
    if idx0 > 0 and is_table_separator(lines[idx0 - 1]):
        return True
    return False


def table_blocks(lines: List[str]) -> List[Tuple[int, int]]:
    blocks: List[Tuple[int, int]] = []
    i = 0
    while i < len(lines):
        if i + 1 < len(lines) and "|" in lines[i] and is_table_separator(lines[i + 1]):
            start = i
            i += 2
            while i < len(lines) and "|" in lines[i] and not is_blank(lines[i]):
                i += 1
            blocks.append((start + 1, i))
        else:
            i += 1
    return blocks


def count_table_cells(line: str) -> int:
    s = line.strip()
    if s.startswith("|"):
        s = s[1:]
    if s.endswith("|"):
        s = s[:-1]
    return len(s.split("|")) if s != "" else 0


def slugify_heading(text: str) -> str:
    # GitHub-like slug; good enough for rumdl's link fragment checks.
    t = text.strip().lower()
    t = re.sub(r"[`*_~\[\]()]", "", t)
    t = re.sub(r"[^\w\s-]", "", t, flags=re.UNICODE)
    t = re.sub(r"\s+", "-", t)
    t = re.sub(r"-+", "-", t).strip("-")
    return t


def inline_link_iter(line: str) -> Iterable[re.Match[str]]:
    # Negative lookbehind avoids images for rules that only want links.
    return re.finditer(r"(?<!!)\[([^\]]*)\]\(([^)]*)\)", line)


def image_link_iter(line: str) -> Iterable[re.Match[str]]:
    return re.finditer(r"!\[([^\]]*)\]\(([^)]*)\)", line)


def ref_def_match(line: str) -> Optional[re.Match[str]]:
    return re.match(r"^\s*\[([^\]]+)\]:\s*(.*)$", line)


# ----------------------------- inline ignores -----------------------------

def parse_rule_words(s: str) -> Optional[Set[str]]:
    rules = split_rules(s)
    return set(rules) if rules else None


def compute_disabled(lines: List[str], code_lines: Set[int]) -> Dict[int, Optional[Set[str]]]:
    disabled: Dict[int, Optional[Set[str]]] = {}
    file_disable: Optional[Set[str]] = None
    for line in lines:
        m = re.search(r"<!--\s*(?:rumdl|markdownlint)-disable-file(?:\s+([^>]*?))?\s*-->", line, re.I)
        if m:
            file_disable = parse_rule_words(m.group(1) or "")
            break
    if file_disable is not None:
        for i in range(1, len(lines) + 1):
            disabled[i] = file_disable
        return disabled
    active: Optional[Set[str]] = set()
    next_disabled: Dict[int, Optional[Set[str]]] = {}
    line_disabled: Dict[int, Optional[Set[str]]] = {}
    stack: List[Optional[Set[str]]] = []
    for i, line in enumerate(lines, 1):
        if active is None:
            disabled[i] = None
        elif active:
            disabled[i] = set(active)
        if i in next_disabled:
            nd = next_disabled[i]
            if nd is None:
                disabled[i] = None
            else:
                disabled[i] = set(disabled.get(i) or set()) | nd if disabled.get(i) is not None else None
        if i in code_lines:
            continue
        # Same-line disable.
        m = re.search(r"<!--\s*(?:rumdl|markdownlint)-disable-line(?:\s+([^>]*?))?\s*-->", line, re.I)
        if m:
            rd = parse_rule_words(m.group(1) or "")
            disabled[i] = rd
        # Next-line disable / prettier-ignore.
        m = re.search(r"<!--\s*(?:rumdl|markdownlint)-disable-next-line(?:\s+([^>]*?))?\s*-->", line, re.I)
        if m:
            next_disabled[i + 1] = parse_rule_words(m.group(1) or "")
        if re.search(r"<!--\s*prettier-ignore\s*-->", line, re.I):
            next_disabled[i + 1] = None
        if re.search(r"<!--\s*(?:rumdl|markdownlint)-capture\s*-->", line, re.I):
            stack.append(None if active is None else set(active))
        if re.search(r"<!--\s*(?:rumdl|markdownlint)-restore\s*-->", line, re.I):
            active = stack.pop() if stack else set()
        m = re.search(r"<!--\s*(?:rumdl|markdownlint)-disable(?:\s+([^>]*?))?\s*-->", line, re.I)
        if m and "disable-line" not in line and "disable-next-line" not in line and "disable-file" not in line:
            rd = parse_rule_words(m.group(1) or "")
            if rd is None:
                active = None
            else:
                if active is not None:
                    active |= rd
        m = re.search(r"<!--\s*(?:rumdl|markdownlint)-enable(?:\s+([^>]*?))?\s*-->", line, re.I)
        if m:
            rd = parse_rule_words(m.group(1) or "")
            if rd is None:
                active = set()
            elif active is not None:
                active -= rd
    return disabled


def is_disabled(disabled: Dict[int, Optional[Set[str]]], line: int, rule: str) -> bool:
    if line not in disabled:
        return False
    v = disabled[line]
    return v is None or rule in v


# ----------------------------- lint rules -----------------------------

def add_issue(issues: List[Issue], iss: Issue, disabled: Dict[int, Optional[Set[str]]]) -> None:
    if not is_disabled(disabled, iss.line, iss.rule):
        issues.append(iss)


def lint_text(text: str, filename: str, cfg: Dict[str, Any], active_rules: Set[str], base_dir: Optional[Path] = None) -> List[Issue]:
    lines = split_lines(text)
    offsets = line_offsets(text)
    code_lines, fences = code_fence_spans(lines)
    fm_span = frontmatter_span(lines)
    disabled = compute_disabled(lines, code_lines)
    issues: List[Issue] = []
    headings = all_headings(lines, code_lines)

    def enabled(rule: str) -> bool:
        return rule in active_rules

    # MD047 can apply to empty/no-newline file as well.
    if enabled("MD047") and text and not text.endswith("\n"):
        ln = len(lines) if lines else 1
        col = len(lines[-1]) + 1 if lines else 1
        add_issue(issues, issue(filename, ln, col, "MD047", "File should end with a single newline character", cfg), disabled)

    # MD001 heading increments
    if enabled("MD001"):
        prev = 0
        for ln, level, txt, style in headings:
            if prev and level > prev + 1:
                msg = f"Expected heading level {prev + 1}, but found heading level {level}"
                add_issue(issues, issue(filename, ln, 1, "MD001", msg, cfg), disabled)
            prev = level

    # MD003 heading style consistency
    if enabled("MD003") and headings:
        desired = str(cfg.get("MD003", {}).get("style", "consistent"))
        if desired == "consistent":
            counts: Dict[str, int] = {"atx": 0, "atx_closed": 0, "setext": 0}
            for _, _, _, st in headings:
                counts[st] = counts.get(st, 0) + 1
            desired = max(counts, key=lambda k: (counts[k], 1 if k == "atx" else 0))
        for ln, level, txt, st in headings:
            if st != desired:
                if desired == "atx":
                    expected = "#" * level + " " + txt
                elif desired == "atx_closed":
                    expected = "#" * level + " " + txt + " " + "#" * level
                else:
                    expected = txt + " (underlined)"
                found = txt if st.startswith("atx") else f"{txt} (underlined with {'=' if level == 1 else '-'})"
                add_issue(issues, issue(filename, ln, 1, "MD003", f"Heading style should be {expected}, found {found}", cfg), disabled)

    # MD018/019/020/021/023 and heading punctuation/spacing rules
    for i, line in enumerate(lines, 1):
        if i in code_lines:
            continue
        # MD023 indented headings
        if enabled("MD023"):
            m = re.match(r"^( +)(#{1,6})(?:\s|\S)", line)
            if m and len(m.group(1)) > 0 and len(m.group(1)) <= 3:
                add_issue(issues, issue(filename, i, 1, "MD023", f"Heading should not be indented by {len(m.group(1))} spaces", cfg), disabled)
        # ATX malformed spacing
        m = re.match(r"^( {0,3})(#{1,6})(.*)$", line)
        if m:
            hashes = m.group(2)
            rest = m.group(3)
            # closed heading without spaces, e.g. #Title#
            if enabled("MD020") and re.match(r"\S.*#\s*$", rest) and not rest.startswith(" "):
                add_issue(issues, issue(filename, i, len(m.group(1)) + len(hashes) + 1, "MD020", "Missing space inside hashes on closed heading (with # at start and end)", cfg), disabled)
            if enabled("MD021") and re.match(r" {2,}.* {2,}#+\s*$", rest):
                sm = re.match(r"( +)", rest)
                em = re.search(r"( +)#+\s*$", rest)
                sc = len(sm.group(1)) if sm else 0
                ec = len(em.group(1)) if em else 0
                add_issue(issues, issue(filename, i, 1, "MD021", f"Multiple spaces ({sc} at start, {ec} at end) inside hashes on closed heading (with # at start and end)", cfg), disabled)
            if enabled("MD018") and rest and not rest.startswith(" ") and not rest.startswith("#"):
                add_issue(issues, issue(filename, i, len(m.group(1)) + len(hashes) + 1, "MD018", f"No space after {'#' * len(hashes)} in heading", cfg), disabled)
            if enabled("MD019"):
                sm = re.match(r"( {2,})\S", rest)
                if sm and not re.search(r"#+\s*$", rest):
                    add_issue(issues, issue(filename, i, len(m.group(1)) + len(hashes) + 1, "MD019", f"Multiple spaces ({len(sm.group(1))}) after {'#' * len(hashes)} in heading", cfg), disabled)

    # MD022 blanks around headings
    if enabled("MD022"):
        above = int(cfg.get("MD022", {}).get("lines-above", 1))
        below = int(cfg.get("MD022", {}).get("lines-below", 1))
        for ln, level, txt, st in headings:
            if ln <= 1 or (fm_span and ln == fm_span[1] + 1):
                pass
            else:
                have = 0
                j = ln - 2
                while j >= 0 and is_blank(lines[j]):
                    have += 1; j -= 1
                if have < above:
                    add_issue(issues, issue(filename, ln, 1, "MD022", f"Expected {above} blank line{'s' if above != 1 else ''} above heading", cfg), disabled)
            if ln < len(lines):
                have = 0
                j = ln
                while j < len(lines) and is_blank(lines[j]):
                    have += 1; j += 1
                if have < below:
                    add_issue(issues, issue(filename, ln, 1, "MD022", f"Expected {below} blank line{'s' if below != 1 else ''} below heading", cfg), disabled)

    # MD024 duplicate headings
    if enabled("MD024"):
        seen: Set[str] = set()
        for ln, level, txt, st in headings:
            key = re.sub(r"\s+", " ", txt.strip()).lower()
            if key in seen:
                col = (lines[ln - 1].find(txt) + 1) if txt and txt in lines[ln - 1] else 1
                add_issue(issues, issue(filename, ln, col, "MD024", f"Duplicate heading: '{txt}'.", cfg, fixable=False), disabled)
            seen.add(key)

    # MD025 single H1
    if enabled("MD025"):
        level_req = int(cfg.get("MD025", {}).get("level", 1))
        found = False
        for ln, level, txt, st in headings:
            if level == level_req:
                if found:
                    col = (lines[ln - 1].find(txt) + 1) if txt and txt in lines[ln - 1] else 1
                    add_issue(issues, issue(filename, ln, col, "MD025", f"Multiple top-level headings (level {level_req}) in the same document", cfg), disabled)
                found = True

    # MD026 trailing punctuation in heading
    if enabled("MD026"):
        punct = str(cfg.get("MD026", {}).get("punctuation", ".,;:!"))
        for ln, level, txt, st in headings:
            t = txt.rstrip()
            if t and t[-1] in punct:
                col = lines[ln - 1].rfind(t[-1]) + 1
                add_issue(issues, issue(filename, ln, col, "MD026", f"Heading '{t}' ends with punctuation '{t[-1]}'", cfg), disabled)

    # MD041 first line H1
    if enabled("MD041"):
        start = 1
        if fm_span:
            start = fm_span[1] + 1
            while start <= len(lines) and is_blank(lines[start - 1]):
                start += 1
        while start <= len(lines) and is_blank(lines[start - 1]):
            start += 1
        if start <= len(lines):
            ah = atx_heading(lines[start - 1])
            req = int(cfg.get("MD041", {}).get("level", 1))
            if not (ah and ah[0] == req):
                add_issue(issues, issue(filename, 1, 1, "MD041", f"First line in file should be a level {req} heading", cfg, fixable=bool(cfg.get("MD041", {}).get("fix", False))), disabled)

    # MD043 required headings
    if enabled("MD043") and cfg.get("MD043", {}).get("headings"):
        expected = [str(x).strip() for x in cfg["MD043"].get("headings", [])]
        actual = [("#" * lvl + " " + txt).strip() for _, lvl, txt, _ in headings]
        cmp_e = expected if cfg.get("MD043", {}).get("match-case", False) else [x.lower() for x in expected]
        cmp_a = actual if cfg.get("MD043", {}).get("match-case", False) else [x.lower() for x in actual]
        if cmp_a != cmp_e:
            for ln, _, _, _ in headings or [(1, 1, "", "")]:
                add_issue(issues, issue(filename, ln, 1, "MD043", "Heading structure does not match the required structure", cfg, fixable=False), disabled)

    # Whitespace and line-level rules
    blank_run = 0
    for i, line in enumerate(lines, 1):
        in_code = i in code_lines
        if enabled("MD009"):
            m = re.search(r"( +)$", line)
            if m:
                n = len(m.group(1))
                br = int(cfg.get("MD009", {}).get("br-spaces", 2))
                strict = bool(cfg.get("MD009", {}).get("strict", False))
                allow_hard = (not strict and n == br and not is_blank(line))
                if not allow_hard:
                    add_issue(issues, issue(filename, i, len(line) - n + 1, "MD009", f"{n} trailing spaces found", cfg, end_col=len(line)+1), disabled)
        if enabled("MD010") and "\t" in line:
            for m in re.finditer("\t", line):
                add_issue(issues, issue(filename, i, m.start() + 1, "MD010", "Found tab for alignment, use spaces instead", cfg), disabled)
        if enabled("MD012"):
            if is_blank(line):
                blank_run += 1
                max_blank = int(cfg.get("MD012", {}).get("maximum", 1))
                if blank_run > max_blank:
                    add_issue(issues, issue(filename, i, 1, "MD012", "Multiple consecutive blank lines between content", cfg), disabled)
            else:
                blank_run = 0
        if enabled("MD013"):
            ll = int(cfg.get("MD013", {}).get("line-length", cfg.get("global", {}).get("line-length", 80)) or 0)
            if ll > 0:
                is_heading = any(h[0] == i for h in headings)
                is_tbl = is_table_line(lines, i - 1)
                check = True
                if in_code and not cfg.get("MD013", {}).get("code-blocks", True):
                    check = False
                if is_heading and not cfg.get("MD013", {}).get("headings", True):
                    check = False
                if is_tbl and not cfg.get("MD013", {}).get("tables", False):
                    check = False
                if (not in_code and not is_heading and not is_tbl) and not cfg.get("MD013", {}).get("paragraphs", True):
                    check = False
                if not cfg.get("MD013", {}).get("strict", False):
                    # Match common markdownlint exceptions: a single long URL or reference definition line.
                    stripped = line.strip()
                    if re.fullmatch(r"<?https?://\S+>?", stripped) or ref_def_match(line):
                        check = False
                width = visual_width(line)
                if check and width > ll:
                    add_issue(issues, issue(filename, i, ll + 1, "MD013", f"Line length {width} exceeds {ll} characters", cfg), disabled)
        if enabled("MD027") and not in_code:
            m = re.match(r"^(>+) {2,}\S", line)
            if m:
                add_issue(issues, issue(filename, i, len(m.group(1)) + 2, "MD027", "Multiple spaces after quote marker (>)", cfg), disabled)
        if enabled("MD064") and not in_code:
            for m in re.finditer(r" {2,}", line):
                # Avoid indentation and trailing hard-break/trailing-space diagnostics.
                if m.start() == 0 or m.end() == len(line):
                    continue
                if bool(cfg.get("MD064", {}).get("allow-sentence-double-space", False)) and len(m.group(0)) == 2 and m.start() > 0 and line[m.start()-1] in ".!?":
                    continue
                add_issue(issues, issue(filename, i, m.start() + 1, "MD064", f"Multiple consecutive spaces ({len(m.group(0))}) found", cfg), disabled)

    # MD028 blockquote blank line between adjacent quote blocks
    if enabled("MD028"):
        for idx, line in enumerate(lines):
            if is_blank(line) and idx > 0 and idx + 1 < len(lines):
                if re.match(r"^>+", lines[idx - 1]) and re.match(r"^>+", lines[idx + 1]):
                    level = len(re.match(r"^(>+)", lines[idx - 1]).group(1))
                    add_issue(issues, issue(filename, idx + 1, 1, "MD028", f"Blank line inside blockquote (level {level})", cfg), disabled)

    # List rules MD004/005/007/030/032/069.  MD029 was observed to be lenient/no-op.
    ul_markers: List[str] = []
    for line in lines:
        m = list_item_match(line)
        if m and m.group("ul"):
            ul_markers.append(m.group("ul"))
    expected_ul = "-"
    if enabled("MD004"):
        style = str(cfg.get("MD004", {}).get("style", "consistent"))
        style_map = {"dash": "-", "asterisk": "*", "plus": "+"}
        if style in style_map:
            expected_ul = style_map[style]
        elif ul_markers:
            counts = {x: ul_markers.count(x) for x in "-+*"}
            expected_ul = max(counts, key=lambda k: (counts[k], 1 if k == "-" else 0))
    for i, line in enumerate(lines, 1):
        if i in code_lines:
            continue
        m = list_item_match(line)
        if not m:
            continue
        indent = len(m.group(1).replace("\t", "    "))
        marker = m.group("ul") or (m.group("ol") + m.group("odelim"))
        spaces = len(m.group("space"))
        if enabled("MD004") and m.group("ul") and marker != expected_ul:
            add_issue(issues, issue(filename, i, indent + 1, "MD004", f"List marker '{marker}' does not match expected style '{expected_ul}'", cfg), disabled)
        if enabled("MD005"):
            exp = (round(indent / 2) * 2) if indent else 0
            if indent % 2 != 0:
                add_issue(issues, issue(filename, i, 1, "MD005", f"Expected indentation of {exp} spaces, found {indent}", cfg), disabled)
        if enabled("MD007") and m.group("ul"):
            depth = round(indent / 2)
            exp = depth * int(cfg.get("MD007", {}).get("indent", 2))
            if indent != exp:
                add_issue(issues, issue(filename, i, 1, "MD007", f"Expected {exp} spaces for indent depth {depth}, found {indent}", cfg), disabled)
        if enabled("MD030"):
            exp_spaces = 1
            if spaces != exp_spaces:
                add_issue(issues, issue(filename, i, indent + len(marker), "MD030", f"Spaces after list markers (Expected: {exp_spaces}; Actual: {spaces})", cfg), disabled)
        if enabled("MD069"):
            if re.match(r"^\s*([-+*])\s+\1\s+", line):
                mm = re.match(r"^\s*([-+*])\s+\1", line)
                dup = (mm.group(1) + " " + mm.group(1)) if mm else ""
                add_issue(issues, issue(filename, i, 1, "MD069", f"Duplicate list marker '{dup}' - likely copy-paste error", cfg), disabled)
    if enabled("MD032"):
        in_list = False
        for i, line in enumerate(lines, 1):
            item = is_list_item(line)
            if item and not in_list:
                if i > 1 and not is_blank(lines[i - 2]) and not is_list_item(lines[i - 2]):
                    add_issue(issues, issue(filename, i, 1, "MD032", "List should be preceded by blank line", cfg), disabled)
                in_list = True
            if not item and not (in_list and line.startswith(" ") and not is_blank(line)):
                if in_list:
                    # The observed default allows lazy continuation; only strict obvious
                    # cases are reported to avoid false positives.
                    pass
                in_list = False

    # Code fence rules MD014/031/040/046/048/070
    if enabled("MD031"):
        for start, end, ch, length, info in fences:
            if start > 1 and not is_blank(lines[start - 2]) and not is_list_item(lines[start - 2]):
                add_issue(issues, issue(filename, start, 1, "MD031", "No blank line before fenced code block", cfg), disabled)
            if end < len(lines) and not is_blank(lines[end]) and not is_list_item(lines[end]):
                add_issue(issues, issue(filename, end, 1, "MD031", "No blank line after fenced code block", cfg), disabled)
    if enabled("MD040"):
        for start, end, ch, length, info in fences:
            if not info:
                fence = ch * length
                add_issue(issues, issue(filename, start, 1, "MD040", f"Code block ({fence}) missing language", cfg), disabled)
    if enabled("MD014") and cfg.get("MD014", {}).get("show-output", True):
        for start, end, ch, length, info in fences:
            j = start + 1
            while j < end:
                content = lines[j - 1]
                cm = re.match(r"^\s*\$\s+(.+)$", content)
                if cm:
                    k = j + 1
                    has_output = False
                    while k < end:
                        nxt = lines[k - 1]
                        if re.match(r"^\s*\$\s+", nxt):
                            break
                        if nxt.strip():
                            has_output = True
                            break
                        k += 1
                    if not has_output:
                        add_issue(issues, issue(filename, j, 1, "MD014", f"Command '{cm.group(1).strip()}' should show output (add example output or remove $ prompt)", cfg), disabled)
                j += 1
    if enabled("MD046"):
        for i, line in enumerate(lines, 1):
            if re.match(r"^ {4}\S", line) and i not in code_lines:
                add_issue(issues, issue(filename, i, 1, "MD046", "Use fenced code blocks", cfg), disabled)
                # one issue per indented block
                # skip following indented lines by relying on duplicate suppression? no-op
    if enabled("MD048") and fences:
        style = str(cfg.get("MD048", {}).get("style", "consistent"))
        expected_ch = "`"
        if style in ("backtick", "backticks"):
            expected_ch = "`"
        elif style in ("tilde", "tildes"):
            expected_ch = "~"
        else:
            counts = {"`": 0, "~": 0}
            for _, _, ch, _, _ in fences:
                counts[ch] += 1
            expected_ch = max(counts, key=lambda k: (counts[k], 1 if k == "`" else 0))
        for start, end, ch, length, info in fences:
            if ch != expected_ch:
                add_issue(issues, issue(filename, start, 1, "MD048", f"Code fence style: use {expected_ch*3} instead of {ch*3}", cfg), disabled)
                add_issue(issues, issue(filename, end, 1, "MD048", f"Code fence style: use {expected_ch*3} instead of {ch*3}", cfg), disabled)
    if enabled("MD070"):
        for start, end, ch, length, info in fences:
            lang = (info.split()[0].lower() if info else "")
            if lang in ("", "md", "markdown"):
                inner_max = 0; inner_line = 0
                for j in range(start + 1, end):
                    m = re.match(rf"^\s*{re.escape(ch)}{{{length},}}", lines[j - 1])
                    if m:
                        n = len(re.match(rf"\s*({re.escape(ch)}+)", lines[j - 1]).group(1))
                        if n >= length:
                            inner_max = max(inner_max, n); inner_line = j; break
                if inner_line:
                    add_issue(issues, issue(filename, start, 1, "MD070", f"Nested {ch*length} at line {inner_line} closes block prematurely — use {ch*(inner_max+1)} for outer fence", cfg, fixable=False), disabled)

    # HTML/links/images/emphasis/inline code
    for i, line in enumerate(lines, 1):
        if i in code_lines:
            continue
        if enabled("MD033"):
            flavor = str(cfg.get("global", {}).get("flavor", "standard")).lower()
            if flavor not in ("mdx",):
                allowed = {str(x).lower() for x in cfg.get("MD033", {}).get("allowed-elements", [])}
                disallowed = {str(x).lower() for x in cfg.get("MD033", {}).get("disallowed-elements", [])}
                for m in re.finditer(r"</?([A-Za-z][A-Za-z0-9-]*)(?:\s[^<>]*)?>", line):
                    tag = m.group(1).lower()
                    if tag.startswith("!") or line[m.start():m.start()+4] == "<!--":
                        continue
                    if disallowed:
                        bad = tag in disallowed
                    else:
                        bad = tag not in allowed
                    if bad:
                        shown = re.match(r"</?[A-Za-z][^>]*>", m.group(0)).group(0)
                        if len(shown) > 40:
                            shown = shown[:37] + "...>"
                        add_issue(issues, issue(filename, i, m.start() + 1, "MD033", f"Inline HTML found: {shown}", cfg, fixable=bool(cfg.get("MD033", {}).get("fix", False))), disabled)
        if enabled("MD034"):
            for m in re.finditer(r"https?://[^\s<>)\]]+", line):
                before = line[m.start()-2:m.start()] if m.start() >= 2 else line[:m.start()]
                after = line[m.end():m.end()+1]
                if (m.start() > 0 and line[m.start()-1] in "(<") or before == "](" or after == ">":
                    continue
                add_issue(issues, issue(filename, i, m.start() + 1, "MD034", f"URL without angle brackets or link formatting: '{m.group(0)}'", cfg), disabled)
        if enabled("MD011"):
            for m in re.finditer(r"\((https?://[^)\s]+)\)\[([^\]]+)\]", line):
                add_issue(issues, issue(filename, i, m.start() + 1, "MD011", f"Reversed link syntax: use [{m.group(2)}]({m.group(1)}) instead", cfg), disabled)
        if enabled("MD039"):
            for m in inline_link_iter(line):
                txt = m.group(1)
                if txt != txt.strip():
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD039", "Remove spaces inside link text", cfg), disabled)
        if enabled("MD042"):
            for m in inline_link_iter(line):
                if m.group(2).strip() == "":
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD042", f"Empty link found: {m.group(0)}", cfg, fixable=False), disabled)
        if enabled("MD045"):
            for m in image_link_iter(line):
                if m.group(1).strip() == "":
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD045", "Image missing alt text (add description for accessibility: ![description](url))", cfg), disabled)
        if enabled("MD062"):
            for m in re.finditer(r"(!?\[[^\]]*\]\()([^)]*)(\))", line):
                dest = m.group(2)
                if dest and dest != dest.strip():
                    lead = len(dest) - len(dest.lstrip())
                    trail = len(dest) - len(dest.rstrip())
                    if lead and trail:
                        msg = "Link destination has leading and trailing whitespace"
                    elif lead:
                        msg = "Link destination has leading whitespace"
                    else:
                        msg = "Link destination has trailing whitespace"
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD062", msg, cfg), disabled)
        if enabled("MD037"):
            for m in re.finditer(r"(\*\*|__)([^\n]*?)(\1)", line):
                content = m.group(2)
                if content and (content[0].isspace() or content[-1].isspace()):
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD037", f"Spaces inside emphasis markers: \"{m.group(0)}\"", cfg), disabled)
            for m in re.finditer(r"(?<!\*)\*([^*\n]*?)\*(?!\*)|(?<!_)_([^_\n]*?)_(?!_)", line):
                content = m.group(1) if m.group(1) is not None else m.group(2)
                # Observed behavior is permissive for '* text *' and '* text*'.
                if content and (not content[0].isspace()) and content[-1].isspace():
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD037", f"Spaces inside emphasis markers: \"{m.group(0)}\"", cfg), disabled)
        if enabled("MD038"):
            for m in re.finditer(r"`([^`]+)`", line):
                content = m.group(1)
                if content.startswith(" ") ^ content.endswith(" "):
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD038", "Spaces inside code span elements", cfg), disabled)
        if enabled("MD036"):
            m = re.match(r"^\s*(\*\*|__|\*|_)([^*_`\[][^*_`\[]*?)\1\s*$", line)
            if m and m.group(2).strip() and not m.group(2).strip().endswith(tuple(cfg.get("MD036", {}).get("punctuation", ".,;:!?"))):
                add_issue(issues, issue(filename, i, 1, "MD036", f"Emphasis used instead of a heading: '{m.group(2).strip()}'", cfg, fixable=bool(cfg.get("MD036", {}).get("fix", False))), disabled)
        if enabled("MD049"):
            # Determine desired emphasis marker by first/majority; default tie '*'.
            style = str(cfg.get("MD049", {}).get("style", "consistent"))
            desired = "*" if style in ("consistent", "asterisk", "*") else "_"
            for m in re.finditer(r"(?<!_)_([^_\s][^_]*?[^_\s])_(?!_)", line):
                if desired == "*":
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD049", "Emphasis should use * instead of _", cfg), disabled)
            for m in re.finditer(r"(?<!\*)\*([^*\s][^*]*?[^*\s])\*(?!\*)", line):
                if desired == "_":
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD049", "Emphasis should use _ instead of *", cfg), disabled)
        if enabled("MD050"):
            style = str(cfg.get("MD050", {}).get("style", "consistent"))
            desired = "**" if style in ("consistent", "asterisk", "**") else "__"
            for m in re.finditer(r"__([^_\s][^_]*?[^_\s])__", line):
                if desired == "**":
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD050", "Strong emphasis should use ** instead of __", cfg), disabled)
            for m in re.finditer(r"\*\*([^*\s][^*]*?[^*\s])\*\*", line):
                if desired == "__":
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD050", "Strong emphasis should use __ instead of **", cfg), disabled)

    # Proper names MD044
    if enabled("MD044") and cfg.get("MD044", {}).get("names"):
        names = [str(x) for x in cfg.get("MD044", {}).get("names", [])]
        for i, line in enumerate(lines, 1):
            if i in code_lines and not cfg.get("MD044", {}).get("code-blocks", False):
                continue
            for name in names:
                pattern = re.compile(r"\b" + re.escape(name) + r"\b", re.I)
                for m in pattern.finditer(line):
                    if m.group(0) != name:
                        add_issue(issues, issue(filename, i, m.start() + 1, "MD044", f"Proper name '{m.group(0)}' should be '{name}'", cfg), disabled)

    # Horizontal rules MD035/065
    hr_lines: List[Tuple[int, str]] = []
    for i, line in enumerate(lines, 1):
        if i in code_lines:
            continue
        if setext_heading_at(lines, i - 1):
            continue
        if is_hr(line):
            hr_lines.append((i, hr_style(line)))
    if enabled("MD035") and hr_lines:
        style = str(cfg.get("MD035", {}).get("style", "consistent"))
        expected = hr_lines[0][1] if style == "consistent" else style
        style_alias = {"dash": "---", "hyphen": "---", "asterisk": "***", "underscore": "___"}
        expected = style_alias.get(expected, expected)
        for ln, st in hr_lines:
            if st != expected:
                add_issue(issues, issue(filename, ln, 1, "MD035", f"Horizontal rule style should be \"{expected}\"", cfg), disabled)
    if enabled("MD065"):
        mb = int(cfg.get("MD065", {}).get("minimum-before", 1))
        ma = int(cfg.get("MD065", {}).get("minimum-after", 1))
        for ln, st in hr_lines:
            if ln > 1:
                have = 0; j = ln - 2
                while j >= 0 and is_blank(lines[j]):
                    have += 1; j -= 1
                if have < mb:
                    add_issue(issues, issue(filename, ln, 1, "MD065", "Missing blank line before horizontal rule", cfg), disabled)
            if ln < len(lines):
                have = 0; j = ln
                while j < len(lines) and is_blank(lines[j]):
                    have += 1; j += 1
                if have < ma:
                    add_issue(issues, issue(filename, ln, len(lines[ln - 1]) + 1, "MD065", "Missing blank line after horizontal rule", cfg), disabled)

    # Tables MD055/056/058/060
    tblocks = table_blocks(lines)
    if enabled("MD055"):
        style = str(cfg.get("MD055", {}).get("style", "consistent"))
        if style != "consistent":
            for start, end in tblocks:
                for ln in range(start, end + 1):
                    s = lines[ln - 1].strip()
                    lead = s.startswith("|"); trail = s.endswith("|")
                    bad = False; desc = style.replace("-", " ")
                    if style == "leading-and-trailing": bad = not (lead and trail); desc = "leading and trailing"
                    elif style == "leading-only": bad = not (lead and not trail); desc = "leading only"
                    elif style == "trailing-only": bad = not (trail and not lead); desc = "trailing only"
                    elif style == "no-leading-or-trailing": bad = lead or trail; desc = "no leading or trailing"
                    if bad:
                        add_issue(issues, issue(filename, ln, 1, "MD055", f"Table pipe style should be {desc}", cfg), disabled)
    if enabled("MD056"):
        for start, end in tblocks:
            expected = count_table_cells(lines[start - 1])
            for ln in range(start + 1, end + 1):
                c = count_table_cells(lines[ln - 1])
                if c != expected:
                    add_issue(issues, issue(filename, ln, 1, "MD056", f"Table row has {c} cells, but expected {expected}", cfg), disabled)
    if enabled("MD058"):
        for start, end in tblocks:
            if start > 1 and not is_blank(lines[start - 2]):
                add_issue(issues, issue(filename, start, 1, "MD058", "Missing blank line before table", cfg), disabled)
            if end < len(lines) and not is_blank(lines[end]):
                add_issue(issues, issue(filename, end, len(lines[end - 1]) + 1, "MD058", "Missing blank line after table", cfg), disabled)
    if enabled("MD060") and cfg.get("MD060", {}).get("enabled", False):
        for start, end in tblocks:
            for ln in range(start, end + 1):
                row = lines[ln - 1]
                if re.search(r"\S\|", row) or re.search(r"\|\S", row):
                    add_issue(issues, issue(filename, ln, 1, "MD060", "Table columns should be aligned", cfg), disabled)

    # References, anchors, styles, relative links, descriptive text
    definitions: Dict[str, Tuple[int, str]] = {}
    used_refs: List[Tuple[int, int, str]] = []
    for i, line in enumerate(lines, 1):
        d = ref_def_match(line)
        if d:
            definitions[d.group(1).lower()] = (i, d.group(2).strip())
        for m in re.finditer(r"!?\[([^\]]+)\]\[([^\]]*)\]", line):
            lab = m.group(2) or m.group(1)
            used_refs.append((i, m.start() + 1, lab.lower()))
    if enabled("MD052"):
        for ln, col, lab in used_refs:
            if lab not in definitions:
                add_issue(issues, issue(filename, ln, col, "MD052", f"Reference '{lab}' not found", cfg, fixable=False), disabled)
    if enabled("MD053"):
        ignored = {str(x).lower() for x in cfg.get("MD053", {}).get("ignored-definitions", [])}
        used = {r[2] for r in used_refs}
        for lab, (ln, _) in definitions.items():
            if lab not in used and lab not in ignored:
                add_issue(issues, issue(filename, ln, 1, "MD053", f"Unused link/image reference: [{lab}]", cfg, fixable=False), disabled)
    if enabled("MD051"):
        anchors: Set[str] = set()
        counts: Dict[str, int] = {}
        for _, _, txt, _ in headings:
            base = slugify_heading(txt)
            slug = base if counts.get(base, 0) == 0 else f"{base}-{counts[base]}"
            counts[base] = counts.get(base, 0) + 1
            anchors.add(slug)
        for i, line in enumerate(lines, 1):
            for m in inline_link_iter(line):
                dest = m.group(2).strip()
                if dest.startswith("#"):
                    a = dest[1:]
                    if a not in anchors:
                        add_issue(issues, issue(filename, i, m.start(2) + 1, "MD051", f"Link anchor '{dest}' does not exist in document headings", cfg, fixable=False), disabled)
    if enabled("MD054"):
        allowed = cfg.get("MD054", {})
        for i, line in enumerate(lines, 1):
            if not allowed.get("inline", True):
                for m in inline_link_iter(line):
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD054", "Link/image style 'inline' is not allowed", cfg, fixable=False), disabled)
            if not allowed.get("full", True):
                for m in re.finditer(r"!?\[[^\]]+\]\[[^\]]+\]", line):
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD054", "Link/image style 'full' is not allowed", cfg, fixable=False), disabled)
            if not allowed.get("collapsed", True):
                for m in re.finditer(r"!?\[[^\]]+\]\[\]", line):
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD054", "Link/image style 'collapsed' is not allowed", cfg, fixable=False), disabled)
            if not allowed.get("autolink", True):
                for m in re.finditer(r"<https?://[^>]+>", line):
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD054", "Link/image style 'autolink' is not allowed", cfg, fixable=False), disabled)
    if enabled("MD057"):
        root = base_dir or Path.cwd()
        for i, line in enumerate(lines, 1):
            for m in list(inline_link_iter(line)) + list(image_link_iter(line)):
                dest = m.group(2).strip()
                if not dest or dest.startswith(('#', 'http://', 'https://', 'mailto:', 'tel:')):
                    continue
                if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", dest):
                    continue
                path_part = dest.split("#", 1)[0].split("?", 1)[0]
                if not path_part:
                    continue
                if not (root / path_part).exists():
                    add_issue(issues, issue(filename, i, m.start(2) + 1, "MD057", f"Relative link '{path_part}' does not exist", cfg, fixable=False), disabled)
    if enabled("MD059"):
        bad_texts = {str(x).lower() for x in cfg.get("MD059", {}).get("prohibited-texts", ["click here", "here", "link", "more"])}
        for i, line in enumerate(lines, 1):
            for m in inline_link_iter(line):
                if m.group(1).strip().lower() in bad_texts:
                    add_issue(issues, issue(filename, i, m.start(1) + 1, "MD059", "Link text should be descriptive", cfg, fixable=False), disabled)

    # Forbidden terms MD061
    if enabled("MD061") and cfg.get("MD061", {}).get("terms"):
        terms = [str(x) for x in cfg.get("MD061", {}).get("terms", [])]
        cs = bool(cfg.get("MD061", {}).get("case-sensitive", True))
        for i, line in enumerate(lines, 1):
            if i in code_lines:
                continue
            for term in terms:
                flags = 0 if cs else re.I
                for m in re.finditer(r"\b" + re.escape(term) + r"\b", line, flags):
                    shown = term if cs else term.upper()
                    add_issue(issues, issue(filename, i, m.start() + 1, "MD061", f"Found forbidden term '{shown}'", cfg, fixable=False), disabled)

    # Heading capitalization MD063
    if enabled("MD063") and cfg.get("MD063", {}).get("enabled", False):
        lower_words = set(cfg.get("MD063", {}).get("lowercase-words", []))
        minl = int(cfg.get("MD063", {}).get("min-level", 1)); maxl = int(cfg.get("MD063", {}).get("max-level", 6))
        for ln, lvl, txt, st in headings:
            if not (minl <= lvl <= maxl):
                continue
            words = re.split(r"(\s+)", txt)
            conv: List[str] = []
            word_idx = 0
            for w in words:
                if w.isspace() or not w:
                    conv.append(w); continue
                bare = re.sub(r"^[^A-Za-z0-9]+|[^A-Za-z0-9]+$", "", w)
                lw = bare.lower()
                if word_idx > 0 and lw in lower_words:
                    newbare = lw
                else:
                    newbare = bare[:1].upper() + bare[1:].lower() if bare else bare
                conv.append(w.replace(bare, newbare, 1))
                word_idx += 1
            newtxt = "".join(conv)
            if newtxt != txt:
                col = lines[ln - 1].find(txt) + 1 if txt in lines[ln - 1] else 1
                add_issue(issues, issue(filename, ln, col, "MD063", f"Heading should use title case: '{txt}' -> '{newtxt}'", cfg), disabled)

    # Footnotes MD066/067/068
    refs: List[Tuple[int, str]] = []
    defs: List[Tuple[int, str, str]] = []
    for i, line in enumerate(lines, 1):
        dm = re.match(r"^\[\^([^\]]+)\]:\s*(.*)$", line)
        if dm:
            defs.append((i, dm.group(1), dm.group(2)))
        for m in re.finditer(r"\[\^([^\]]+)\]", line):
            if not dm or m.start() != 0:
                refs.append((i, m.group(1)))
    def_labels = {d[1] for d in defs}
    ref_labels = [r[1] for r in refs]
    if enabled("MD066"):
        for ln, lab in refs:
            if lab not in def_labels:
                add_issue(issues, issue(filename, ln, 1, "MD066", f"Footnote reference '[^{lab}]' has no corresponding definition", cfg, fixable=False), disabled)
        for ln, lab, body in defs:
            if lab not in ref_labels:
                add_issue(issues, issue(filename, ln, 1, "MD066", f"Footnote definition '[^{lab}]' is never referenced", cfg, fixable=False), disabled)
    if enabled("MD067") and refs and defs:
        order = []
        for _, lab in refs:
            if lab not in order:
                order.append(lab)
        for idx, (ln, lab, _) in enumerate(defs):
            if idx < len(order) and lab != order[idx]:
                add_issue(issues, issue(filename, ln, 1, "MD067", f"Footnote definition '[^{lab}]' is out of order; expected '[^{order[idx]}]' next (based on reference order)", cfg, fixable=False), disabled)
                break
    if enabled("MD068"):
        for ln, lab, body in defs:
            if body.strip() == "":
                add_issue(issues, issue(filename, ln, 1, "MD068", f"Footnote definition '[^{lab}]' is empty", cfg, fixable=False), disabled)

    # Frontmatter MD071/072
    if fm_span:
        if enabled("MD071") and fm_span[1] < len(lines) and not is_blank(lines[fm_span[1]]):
            add_issue(issues, issue(filename, fm_span[1], 1, "MD071", "Missing blank line after frontmatter", cfg), disabled)
        if enabled("MD072") and cfg.get("MD072", {}).get("enabled", False) and lines[0].strip() == "---":
            keys: List[Tuple[int, str]] = []
            for ln in range(2, fm_span[1]):
                m = re.match(r"^([A-Za-z0-9_-]+):", lines[ln - 1])
                if m:
                    keys.append((ln, m.group(1)))
            sorted_keys = sorted([k for _, k in keys], key=lambda x: x.lower())
            actual_keys = [k for _, k in keys]
            if actual_keys != sorted_keys and keys:
                # Find first inversion.
                for idx in range(len(actual_keys) - 1):
                    if actual_keys[idx].lower() > actual_keys[idx + 1].lower():
                        add_issue(issues, issue(filename, keys[idx][0], 1, "MD072", f"YAML frontmatter keys are not sorted alphabetically: '{actual_keys[idx+1]}' should come before '{actual_keys[idx]}'", cfg), disabled)
                        break

    # TOC validation MD073
    if enabled("MD073") and cfg.get("MD073", {}).get("enabled", False):
        toc_start = toc_end = None
        for i, line in enumerate(lines, 1):
            if re.search(r"<!--\s*toc\s*-->", line, re.I):
                toc_start = i
            if re.search(r"<!--\s*tocstop\s*-->", line, re.I):
                toc_end = i
                break
        if toc_start and toc_end and toc_end > toc_start:
            toc_text = "\n".join(lines[toc_start:toc_end-1])
            toc_entries = [m.group(1).strip() for m in re.finditer(r"\[[^\]]+\]\(#([^\)]+)\)", toc_text)]
            minl = int(cfg.get("MD073", {}).get("min-level", 2)); maxl = int(cfg.get("MD073", {}).get("max-level", 4))
            target = [(ln, txt, slugify_heading(txt)) for ln, lvl, txt, st in headings if ln > toc_end and minl <= lvl <= maxl]
            for ln, txt, slug in target:
                if slug not in toc_entries:
                    colline = toc_start + 1
                    while colline < toc_end and is_blank(lines[colline - 1]):
                        colline += 1
                    add_issue(issues, issue(filename, colline, 1, "MD073", f"Table of Contents does not match document headings: Missing entry: '{txt}' (line {ln})", cfg), disabled)
                    break

    # Attach simple fix metadata for JSON output based on whole-line ranges.
    offs = offsets
    for iss in issues:
        if iss.fixable:
            start = offs[iss.line - 1] if 0 <= iss.line - 1 < len(offs) else 0
            end = start + (len(lines[iss.line - 1]) if 0 <= iss.line - 1 < len(lines) else 0)
            iss.fix = {"range": {"start": start, "end": end}, "replacement": ""}
    issues.sort(key=lambda x: (x.file, x.line, x.column, x.rule))
    return issues
PY"}

