def rule_obj(r: Dict[str, Any]) -> Dict[str, Any]:
    return {"code":r["code"],"name":r["name"],"aliases":r.get("aliases",[]),"summary":r["summary"],"category":r["category"],"fix":"Fix is always available." if r["code"] != "MD033" and r["code"] != "MD054" and r["code"] != "MD059" else "No automatic fix available.","fix_availability":"Always" if r["code"] not in ("MD033","MD054","MD059") else "None","url":f"https://rumdl.dev/{r['code'].lower()}/"}


def command_rule(args: List[str]) -> int:
    fmt="text"; fixable=False; category=None; explain=False; list_categories=False; rule_name=None
    i=0
    while i < len(args):
        a=args[i]
        if a in ("-h","--help"):
            print(f"""Show information about a rule or list all rules

Usage: {PROGRAM} rule [OPTIONS] [RULE]

Arguments:
  [RULE]  Rule name or ID (optional, omit to list all rules)

Options:
  -o, --output-format <FORMAT>  Output format: text, json, or json-lines [default: text]
  -f, --fixable                 Filter to only fixable rules
  -c, --category <CATEGORY>     Filter by category (use --list-categories to see options)
      --explain                 Include full documentation in output (for json/json-lines)
      --list-categories         List available categories and exit
      --color <COLOR>           Control colored output: auto, always, never [default: auto]
      --config <CONFIG>         Path to configuration file
      --no-config               Ignore all configuration files and use built-in defaults
      --isolated                Ignore all configuration files (alias for --no-config)
  -h, --help                    Print help"""); return 0
        elif a in ("-o","--output-format"):
            i+=1; fmt=args[i]
        elif a in ("-f","--fixable"): fixable=True
        elif a in ("-c","--category"):
            i+=1; category=args[i]
        elif a=="--explain": explain=True
        elif a=="--list-categories": list_categories=True
        elif a in ("--color","--config"):
            i+=1
        elif a in ("--no-config","--isolated"):
            pass
        elif not a.startswith("-"):
            rule_name=a
        i+=1
    if list_categories:
        cats: Dict[str,int]={}
        for r in RULES: cats[r["category"]]=cats.get(r["category"],0)+1
        print("Available categories:")
        for c in sorted(cats): print(f"  {c} ({cats[c]} rules)")
        return 0
    rows=[r for r in RULES if (not category or r["category"]==category)]
    if fixable:
        rows=[r for r in rows if rule_obj(r)["fix_availability"] != "None"]
    if rule_name:
        code=normalize_rule_id(rule_name)
        # Observed 'line-length' is not accepted by this command despite docs; keep code/name lookup for friendliness except exact observed? Accepting more is harmless for most.
        if not code:
            print(f"Rule '{rule_name}' not found."); return 2
        r=RULE_BY_CODE[code]
        if fmt=="json": print(json.dumps(rule_obj(r), indent=2)); return 0
        if fmt=="json-lines": print(json.dumps(rule_obj(r), separators=(",",":"))); return 0
        print(f"{r['code']} - {r['summary']}\n")
        print(f"Name: {r['name']}")
        print(f"Category: {r['category']}")
        print(f"Fix: {rule_obj(r)['fix']}")
        print(f"Documentation: https://rumdl.dev/{r['code'].lower()}/")
        return 0
    objs=[rule_obj(r) for r in rows]
    if fmt=="json": print(json.dumps(objs, indent=2)); return 0
    if fmt=="json-lines":
        for o in objs: print(json.dumps(o, separators=(",",":")))
        return 0
    title="Available rules"
    extras=[]
    if fixable: extras.append("fixable")
    if category: extras.append(f"category={category}")
    if extras: title += " (" + ", ".join(extras) + ")"
    print(title + ":")
    for r in rows: print(f"  {r['code']} - {r['summary']}")
    if category: print(f"\nTotal: {len(rows)} rules")
    return 0


def command_explain(args: List[str]) -> int:
    if not args or args[0] in ("-h","--help"):
        print(f"""Explain a rule with detailed information and examples

Usage: {PROGRAM} explain [OPTIONS] <RULE>

Arguments:
  <RULE>  Rule name or ID to explain

Options:
      --color <COLOR>    Control colored output: auto, always, never [default: auto]
      --config <CONFIG>  Path to configuration file
      --no-config        Ignore all configuration files and use built-in defaults
      --isolated         Ignore all configuration files (alias for --no-config)
  -h, --help             Print help"""); return 0 if args else 2
    rule=args[0]
    code=normalize_rule_id(rule)
    if not code:
        print(f"Rule '{rule}' not found."); return 2
    path=Path("docs")/(code.lower()+".md")
    if path.exists():
        txt=path.read_text(errors="ignore")
        # Light rendering: strip frontmatter and markdown comment enable/disable markers.
        txt=re.sub(r"^---.*?---\s*", "", txt, flags=re.S)
        txt=re.sub(r"<!--\s*rumdl-(?:disable|enable)[^>]*-->\n?", "", txt)
        print(txt.strip())
    else:
        r=RULE_BY_CODE[code]
        print(f"{code} - {r['summary']}\n\nDocumentation: https://rumdl.dev/{code.lower()}/")
    return 0


