def command_config(args: List[str]) -> int:
    if args and args[0] in ("-h","--help"):
        print(f"""Show configuration or query a specific key

Usage: {PROGRAM} config [OPTIONS] [COMMAND]

Commands:
  get   Query a specific config key (e.g. global.exclude or MD013.line_length)
  file  Show the absolute path of the configuration file that was loaded
  help  Print this message or the help of the given subcommand(s)

Options:
      --defaults         Show only the default configuration values
      --no-defaults      Show only non-default configuration values (exclude defaults)
      --output <OUTPUT>  Output format (e.g. toml, json)
      --color <COLOR>    Control colored output: auto, always, never [default: auto]
      --config <CONFIG>  Path to configuration file
      --no-config        Ignore all configuration files and use built-in defaults
      --isolated         Ignore all configuration files (alias for --no-config)
  -h, --help             Print help"""); return 0
    defaults=False; no_defaults=False; outfmt="text"; config_path=None; no_config=False; cmd=None; key=None
    i=0
    while i<len(args):
        a=args[i]
        if a=="--defaults": defaults=True
        elif a=="--no-defaults": no_defaults=True
        elif a=="--output": i+=1; outfmt=args[i]
        elif a=="--config": i+=1; config_path=args[i]
        elif a in ("--no-config","--isolated"): no_config=True
        elif a=="--color": i+=1
        elif a in ("get","file"):
            cmd=a
            if a=="get" and i+1<len(args): i+=1; key=args[i]
        elif a=="help": return command_config(["--help"])
        i+=1
    try:
        loaded=load_config(config_path,no_config or defaults)
    except Exception as ex:
        eprint(f"Error: {ex}"); return 2
    cfg=loaded.data
    if cmd=="file":
        if loaded.path: print(str(loaded.path))
        else: print("No configuration file found")
        return 0
    if cmd=="get":
        if not key:
            eprint(f"error: the following required arguments were not provided:\n  <KEY>"); return 2
        val,nkey=get_config_value(cfg,key)
        source="default"
        if loaded.path and (nkey.split('.')[0] in loaded.changed or loaded.source=="pyproject.toml"):
            source=loaded.source
        print(f"{nkey} = {toml_value(val)} [from {source}]")
        return 0
    if outfmt=="json":
        print(json.dumps(cfg, indent=2)); return 0
    if defaults:
        print(config_to_toml(DEFAULT_CONFIG), end=""); return 0
    if no_defaults:
        partial={k:v for k,v in cfg.items() if json.dumps(v,sort_keys=True)!=json.dumps(DEFAULT_CONFIG.get(k),sort_keys=True)}
        print(config_to_toml(partial), end=""); return 0
    # The real command annotates sources; a TOML-ish view is most useful.
    print(config_to_toml(cfg), end="")
    return 0


