def command_server(args: List[str]) -> int:
    if args and args[0] in ("-h","--help"):
        print(f"""Start the Language Server Protocol server

Usage: {PROGRAM} server [OPTIONS]

Options:
      --port <PORT>      TCP port to listen on (for debugging)
      --stdio            Use stdio for communication (default)
  -v, --verbose          Enable verbose logging
  -c, --config <CONFIG>  Path to rumdl configuration file
      --color <COLOR>    Control colored output: auto, always, never [default: auto]
      --no-config        Ignore all configuration files and use built-in defaults
      --isolated         Ignore all configuration files (alias for --no-config)
  -h, --help             Print help"""); return 0
    # Minimal stdio LSP loop: respond to initialize/shutdown and ignore notifications.
    buf=sys.stdin.buffer
    out=sys.stdout.buffer
    while True:
        headers={}
        line=buf.readline()
        if not line: break
        while line and line.strip():
            if b":" in line:
                k,v=line.decode(errors="ignore").split(":",1); headers[k.lower()]=v.strip()
            line=buf.readline()
        try: length=int(headers.get("content-length","0"))
        except ValueError: length=0
        if length<=0: continue
        body=buf.read(length)
        try: msg=json.loads(body.decode())
        except Exception: continue
        if "id" in msg and msg.get("method")=="initialize":
            resp={"jsonrpc":"2.0","id":msg["id"],"result":{"capabilities":{"textDocumentSync":1,"documentFormattingProvider":True}}}
        elif "id" in msg and msg.get("method")=="shutdown":
            resp={"jsonrpc":"2.0","id":msg["id"],"result":None}
        elif msg.get("method")=="exit":
            break
        else:
            continue
        data=json.dumps(resp,separators=(",",":")).encode()
        out.write(f"Content-Length: {len(data)}\r\n\r\n".encode()+data); out.flush()
    return 0


