def strip_global_options(argv: List[str]) -> Tuple[List[str], Dict[str,Any]]:
    rest=[]; opts={"config":None,"no_config":False}
    i=0
    while i<len(argv):
        a=argv[i]
        if a in ("--color","--config") and i+1<len(argv):
            if a=="--config": opts["config"]=argv[i+1]
            i+=2; continue
        if a in ("--no-config","--isolated"):
            opts["no_config"]=True; i+=1; continue
        rest.append(a); i+=1
    return rest, opts


def main(argv: List[str]) -> int:
    if not argv:
        eprint(MAIN_HELP.rstrip()); return 2
    if argv[0] in ("-h","--help"):
        print(MAIN_HELP.rstrip()); return 0
    if argv[0] in ("-V","--version"):
        print(f"rumdl {VERSION}"); return 0
    # Help pseudo-command.
    if argv[0] == "help":
        if len(argv)==1: print(MAIN_HELP.rstrip()); return 0
        return dispatch(argv[1], ["--help"] + argv[2:])
    return dispatch(argv[0], argv[1:])


def dispatch(cmd: str, args: List[str]) -> int:
    if cmd == "check": return command_check(args, False)
    if cmd == "fmt": return command_check(args, True)
    if cmd == "init": return command_init(args)
    if cmd == "rule": return command_rule(args)
    if cmd == "explain": return command_explain(args)
    if cmd == "config": return command_config(args)
    if cmd == "version": return command_version(args)
    if cmd == "schema": return command_schema(args)
    if cmd == "import": return command_import(args)
    if cmd == "completions": return command_completions(args)
    if cmd == "clean": return command_clean(args)
    if cmd == "vscode": return command_vscode(args)
    if cmd == "server": return command_server(args)
    if cmd in ("-h","--help"):
        print(MAIN_HELP.rstrip()); return 0
    eprint(f"error: unrecognized subcommand '{cmd}'\n\nUsage: {PROGRAM} [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.")
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
