def normalize_heading_line(line: str) -> str:
    m = re.match(r"^(\s*)(#{1,6})\s*(.*?)\s*(#+)?\s*$", line)
    if not m:
        return line
    level = len(m.group(2))
    text = m.group(3).strip()
    closing = bool(m.group(4))
    if closing:
        return f"{'#'*level} {text} {'#'*level}"
    return f"{'#'*level} {text}" if text else "#" * level


