    if "MD058" in active_rules:
        out=[]; i=0
        blocks = table_blocks(lines); starts={a for a,b in blocks}; ends={b for a,b in blocks}
        for idx,s in enumerate(lines,1):
            if idx in starts and out and not is_blank(out[-1]): out.append("")
            out.append(s)
            if idx in ends and idx < len(lines) and not is_blank(lines[idx]): out.append("")
        lines=out
    if "MD055" in active_rules and str(cfg.get("MD055", {}).get("style", "consistent")) == "leading-and-trailing":
        out=[]
        for s in lines:
            if "|" in s and not is_blank(s):
                cells=[c.strip() for c in s.strip().strip("|").split("|")]
                s="| " + " | ".join(cells) + " |"
            out.append(s)
        lines=out
    if "MD056" in active_rules:
        blocks=table_blocks(lines)
        for start,end in blocks:
            expected=count_table_cells(lines[start-1])
            for idx in range(start,end+1):
                c=count_table_cells(lines[idx-1])
                if c < expected:
                    stripped=lines[idx-1].rstrip()
                    if stripped.endswith("|"):
                        stripped=stripped[:-1] + " |"*(expected-c) + " |"
                    else:
                        stripped += " |"*(expected-c)
                    lines[idx-1]=stripped
    if "MD060" in active_rules and cfg.get("MD060", {}).get("enabled", False):
        out=[]
        for s in lines:
            if "|" in s and not is_blank(s):
                cells=[c.strip() for c in s.strip().strip("|").split("|")]
                s="| " + " | ".join(cells) + " |"
            out.append(s)
        lines=out

    # MD063 heading title case.
    if "MD063" in active_rules and cfg.get("MD063", {}).get("enabled", False):
        lower=set(cfg.get("MD063", {}).get("lowercase-words", []))
        out=[]
        for s in lines:
            ah=atx_heading(s)
            if ah:
                words=ah[1].split(" "); conv=[]
                for j,w in enumerate(words):
                    lw=w.lower(); conv.append(lw if j>0 and lw in lower else (lw[:1].upper()+lw[1:]))
                s="#"*ah[0]+" "+" ".join(conv)
            out.append(s)
        lines=out

    # MD064 collapse multiple spaces (not indentation/trailing).
    if "MD064" in active_rules:
        out=[]
        for s in lines:
            prefix=re.match(r"^ *", s).group(0)
            body=s[len(prefix):]
            trailing=""
            mt=re.search(r" +$", body)
            if mt:
                trailing=mt.group(0); body=body[:-len(trailing)]
            body=re.sub(r" {2,}", " ", body)
            out.append(prefix+body+trailing)
        lines=out

    # Frontmatter rules.
    if "MD071" in active_rules:
        fm=frontmatter_span(lines)
        if fm and fm[1] < len(lines) and not is_blank(lines[fm[1]]):
            lines.insert(fm[1], "")
    if "MD072" in active_rules and cfg.get("MD072", {}).get("enabled", False):
        fm=frontmatter_span(lines)
        if fm and lines[0].strip()=="---":
            body=lines[1:fm[1]-1]
            keyed=[]; other=[]
            for l in body:
                if re.match(r"^[A-Za-z0-9_-]+:", l): keyed.append(l)
                else: other.append(l)
            lines= [lines[0]] + sorted(keyed, key=lambda x:x.split(":",1)[0].lower()) + other + [lines[fm[1]-1]] + lines[fm[1]:]

    # MD073 regenerate simple TOC.
    if "MD073" in active_rules and cfg.get("MD073", {}).get("enabled", False):
        code_lines,_=code_fence_spans(lines); heads=all_headings(lines, code_lines)
        ts=te=None
        for i,l in enumerate(lines):
            if re.search(r"<!--\s*toc\s*-->", l, re.I): ts=i
            if re.search(r"<!--\s*tocstop\s*-->", l, re.I): te=i; break
        if ts is not None and te is not None and te>ts:
            minl=int(cfg.get("MD073", {}).get("min-level",2)); maxl=int(cfg.get("MD073", {}).get("max-level",4)); indent=int(cfg.get("MD073", {}).get("indent",2))
            entries=[]
            for ln,lvl,txt,st in heads:
                if ln-1>te and minl<=lvl<=maxl:
                    entries.append(" "*(indent*(lvl-minl))+f"- [{txt}](#{slugify_heading(txt)})")
            lines=lines[:ts+1]+[""]+entries+[""]+lines[te:]

    # MD013 reflow optional.
    if "MD013" in active_rules and cfg.get("MD013", {}).get("reflow", False):
        width=int(cfg.get("MD013", {}).get("line-length", 80))
        if width>0:
            lines=reflow_paragraphs(lines,width)

    # MD047 final newline.
    result="\n".join(lines)
    if text.endswith("\n") or "MD047" in active_rules or had_final_nl:
        result += "\n"
    return result


# ----------------------------- output formats -----------------------------

def format_issue_text(iss: Issue, concise: bool = False) -> str:
    suffix = ""
    if not concise:
        if iss.fixed:
            suffix = " [fixed]"
        elif iss.fixable:
            suffix = " [*]"
    return f"{iss.file}:{iss.line}:{iss.column}: [{iss.rule}] {iss.message}{suffix}"


def summary_line(nissues: int, nfiles: int, elapsed_ms: int, fixed: Optional[int] = None) -> str:
    file_word = "file" if nfiles == 1 else "files"
    if nissues == 0:
        return f"Success: No issues found in {nfiles} {file_word} ({elapsed_ms}ms)"
    if fixed is None:
        return f"Issues: Found {nissues} issues in {nfiles} {file_word} ({elapsed_ms}ms)"
    return f"Fixed: Fixed {fixed}/{nissues} issues in {nfiles} {file_word} ({elapsed_ms}ms)"


def output_issues(issues: List[Issue], nfiles: int, fmt: str, elapsed_ms: int, quiet: bool = False, silent: bool = False, fixed_count: Optional[int] = None, include_summary: bool = True, stream: Any = sys.stdout, statistics: bool = False) -> None:
    if silent:
        return
    n = len(issues)
    if fmt in ("json",):
        print(json.dumps([x.to_json(include_fix=True) for x in issues], indent=2), file=stream)
        return
    if fmt == "gitlab":
        arr=[]
        for x in issues:
            arr.append({"description": x.message, "check_name": x.rule, "fingerprint": f"{x.file}-{x.line}-{x.column}-{x.rule}", "severity": "major" if x.severity == "error" else "minor", "location": {"path": x.file, "lines": {"begin": x.line}}})
        print(json.dumps(arr, indent=2), file=stream); return
    if fmt == "sarif":
        rules=[]; seen=set()
        for x in issues:
            if x.rule not in seen:
                seen.add(x.rule); rules.append({"id": x.rule, "name": x.rule, "shortDescription": {"text": f"Markdown rule {x.rule}"}, "fullDescription": {"text": f"Markdown linting rule {x.rule}"}})
        sar={"$schema":"https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json","version":"2.1.0","runs":[{"tool":{"driver":{"name":"rumdl","version":VERSION,"informationUri":"https://github.com/rvben/rumdl","rules":rules}},"results":[{"ruleId":x.rule,"level":x.severity,"message":{"text":x.message},"locations":[{"physicalLocation":{"artifactLocation":{"uri":x.file},"region":{"startLine":x.line,"startColumn":x.column}}}]} for x in issues]}]}
        print(json.dumps(sar, indent=2), file=stream); return
    if fmt == "junit":
        print('<?xml version="1.0" encoding="UTF-8"?>', file=stream)
        print(f'<testsuites name="rumdl" tests="{max(n,1 if nfiles else 0)}" failures="{n}" errors="0" time="{elapsed_ms/1000:.3f}">', file=stream)
        byfile: Dict[str,List[Issue]]={}
        for x in issues: byfile.setdefault(x.file,[]).append(x)
        if not byfile:
            byfile={"rumdl":[]}
        for f, xs in byfile.items():
            print(f'  <testsuite name="{html.escape(f)}" tests="{max(len(xs),1)}" failures="{len(xs)}" errors="0" time="0.000">', file=stream)
            if xs:
                for x in xs:
                    print(f'    <testcase name="Lint {html.escape(f)}" classname="rumdl" time="0.000">', file=stream)
                    print(f'      <failure type="{x.rule}" message="{html.escape(x.message)}">{html.escape(x.message)} at line {x.line}, column {x.column}</failure>', file=stream)
                    print('    </testcase>', file=stream)
            else:
                print(f'    <testcase name="Lint {html.escape(f)}" classname="rumdl" time="0.000"/>', file=stream)
            print('  </testsuite>', file=stream)
        print('</testsuites>', file=stream); return

    if fmt == "grouped":
        byfile: Dict[str, Dict[str, List[Issue]]] = {}
        for x in issues:
            byfile.setdefault(x.file, {}).setdefault(x.rule, []).append(x)
        for f, byrule in byfile.items():
            print(f"{f}:", file=stream)
            for r, xs in byrule.items():
                print(f"  {r}:", file=stream)
                for x in xs:
                    fx = " (fixed)" if x.fixed else (" (fixable)" if x.fixable else "")
                    print(f"    {x.line}:{x.column} {x.message}{fx}", file=stream)
    else:
        for x in issues:
            if fmt == "json-lines":
                print(json.dumps({k:v for k,v in x.to_json(False).items()}, separators=(",", ":")), file=stream)
            elif fmt == "github":
                sev = "error" if x.severity == "error" else "warning"
                extra = ""
                if x.end_line and x.end_column:
                    extra = f",endLine={x.end_line},endColumn={x.end_column}"
                print(f"::{sev} file={x.file},line={x.line},col={x.column}{extra},title={x.rule}::{x.message}", file=stream)
            elif fmt == "pylint":
                print(f"{x.file}:{x.line}:{x.column}: [C{x.rule}] {x.message}", file=stream)
            elif fmt == "azure":
                sev = "error" if x.severity == "error" else "warning"
                print(f"##vso[task.logissue type={sev};sourcepath={x.file};linenumber={x.line};columnnumber={x.column};code={x.rule}]{x.message}", file=stream)
            else:
                print(format_issue_text(x, concise=(fmt == "concise")), file=stream)
    if include_summary and not quiet:
        print("", file=stream)
        print(summary_line(n, nfiles, elapsed_ms, fixed_count), file=stream)
        if n and fixed_count is None:
            fixable = sum(1 for x in issues if x.fixable)
            if fixable:
                print(f"Run `rumdl fmt` to automatically fix {fixable} of the {n} issues", file=stream)
        if statistics and n:
            print("", file=stream)
            print("Rule Violation Statistics:", file=stream)
            print("Rule     Violations   Fixable  Percentage", file=stream)
            print("--------------------------------------------------", file=stream)
            by: Dict[str, List[Issue]] = {}
            for x in issues: by.setdefault(x.rule, []).append(x)
            for r in sorted(by):
                xs=by[r]; fx=sum(1 for x in xs if x.fixable); pct=100*len(xs)/n
                print(f"{r:<8} {len(xs):<12} {fx:<8} {pct:.1f}%", file=stream)
            print("--------------------------------------------------", file=stream)
            print(f"Total    {n:<12} {sum(1 for x in issues if x.fixable):<8} 100.0%", file=stream)
    elif n == 0 and include_summary and not quiet:
        print("", file=stream)
        print(summary_line(0, nfiles, elapsed_ms, None), file=stream)


# ----------------------------- file discovery/rule selection -----------------------------

def path_matches(path: Path, patterns: Sequence[str]) -> bool:
    s = str(path).replace(os.sep, "/")
    name = path.name
    for p in patterns:
        pp = p.replace(os.sep, "/")
        if pp.endswith("/"):
            pp = pp[:-1]
        if fnmatch.fnmatch(s, pp) or fnmatch.fnmatch(name, pp) or s.startswith(pp.rstrip("/") + "/"):
            return True
    return False


def read_gitignore(root: Path) -> List[str]:
    pats=[]
    gi=root/".gitignore"
    if gi.exists():
        try:
            for line in gi.read_text(errors="ignore").splitlines():
                line=line.strip()
                if line and not line.startswith("#") and not line.startswith("!"):
                    pats.append(line)
        except Exception:
            pass
    return pats


def collect_files(paths: List[str], cfg: Dict[str, Any], include: List[str], exclude: List[str], respect_gitignore: bool, force_exclude: bool) -> List[Path]:
    ex = [] if cfg.get("_no_exclude") else list(cfg.get("global", {}).get("exclude", [])) + exclude
    inc = list(cfg.get("global", {}).get("include", [])) + include
    ex += [".git", ".rumdl_cache"]
    gitpats = read_gitignore(Path.cwd()) if respect_gitignore else []
    files: List[Path] = []
    exts = {".md", ".markdown", ".mdown", ".mkdn", ".mdx", ".qmd"}
    def accept(p: Path, explicit: bool=False) -> bool:
        rel = p if not p.is_absolute() else Path(os.path.relpath(p, Path.cwd()))
        if (force_exclude or not explicit) and (path_matches(rel, ex) or path_matches(rel, gitpats)):
            return False
        if inc and not path_matches(rel, inc):
            return False
        return True
    for ps in paths:
        if ps == "-":
            continue
        p = Path(ps)
        if p.is_dir():
            for root, dirs, names in os.walk(p):
                rpath = Path(root)
                dirs[:] = [d for d in sorted(dirs) if not path_matches(rpath/d, ex) and not path_matches(rpath/d, gitpats)]
                for n in sorted(names):
                    fp = rpath/n
                    if fp.suffix.lower() in exts and accept(fp, explicit=False):
                        files.append(fp)
        elif p.exists():
            if accept(p, explicit=True):
                files.append(p)
        else:
            raise FileNotFoundError(f"No such file or directory: {ps}")
    # stable unique list
    seen=set(); out=[]
    for f in files:
        key=str(f)
        if key not in seen:
            seen.add(key); out.append(f)
    return out


def selected_rules(cfg: Dict[str, Any], cli_enable: List[str], cli_disable: List[str], extend_enable: List[str], extend_disable: List[str]) -> Set[str]:
    default_enabled = {r["code"] for r in RULES if r["code"] not in OPT_IN_RULES}
    # Opt-in rules are active when explicitly enabled in their config.
    for r in OPT_IN_RULES:
        if cfg.get(r, {}).get("enabled", False):
            default_enabled.add(r)
    conf_enable = []
    for x in cfg.get("global", {}).get("enable", []) or []:
        c = normalize_rule_id(str(x))
        if c: conf_enable.append(c)
    conf_disable = []
    for x in cfg.get("global", {}).get("disable", []) or []:
        c = normalize_rule_id(str(x))
        if c: conf_disable.append(c)
    if cli_enable:
        rules = set(cli_enable)
    elif conf_enable:
        rules = set(conf_enable)
    else:
        rules = set(default_enabled)
    rules |= set(extend_enable)
    # [MDxxx] enabled=false disables; enabled=true enables.
    for r in RULE_BY_CODE:
        if cfg.get(r, {}).get("enabled") is True:
            rules.add(r)
        elif cfg.get(r, {}).get("enabled") is False and r not in OPT_IN_RULES:
            rules.discard(r)
    rules -= set(conf_disable)
    rules -= set(cli_disable)
    rules -= set(extend_disable)
    return rules


def apply_per_file_ignores(rules: Set[str], file_path: str, cfg: Dict[str, Any]) -> Set[str]:
    out = set(rules)
    p = Path(file_path)
    rel = str(p).replace(os.sep, "/")
    ignores = cfg.get("per-file-ignores", {}) or {}
    for pat, vals in ignores.items():
        pats = [str(pat)]
        # brace expansion for simple {a,b}
        m = re.search(r"\{([^{}]+)\}", str(pat))
        if m:
            pats = [str(pat)[:m.start()] + part + str(pat)[m.end():] for part in m.group(1).split(",")]
        if any(fnmatch.fnmatch(rel, pp) or fnmatch.fnmatch(p.name, pp) for pp in pats):
            for v in vals:
                c = normalize_rule_id(str(v))
                if c: out.discard(c)
    return out


# ----------------------------- command parsers -----------------------------

@dataclass
class CheckOptions:
    paths: List[str] = field(default_factory=list)
    fix: bool = False
    diff: bool = False
    check: bool = False
    list_rules: bool = False
    disable: List[str] = field(default_factory=list)
    enable: List[str] = field(default_factory=list)
    extend_enable: List[str] = field(default_factory=list)
    extend_disable: List[str] = field(default_factory=list)
    exclude: List[str] = field(default_factory=list)
    include: List[str] = field(default_factory=list)
    no_exclude: bool = False
    respect_gitignore: Optional[bool] = None
    verbose: bool = False
    quiet: bool = False
    silent: bool = False
    profile: bool = False
    statistics: bool = False
    config: Optional[str] = None
    no_config: bool = False
    output_format: str = "text"
    show_full_path: bool = False
    flavor: Optional[str] = None
    stdin: bool = False
    stdin_filename: Optional[str] = None
    stderr: bool = False
    force_exclude: bool = False
    no_cache: bool = False
    cache_dir: str = ".rumdl_cache"
    fail_on: str = "any"
    color: str = "auto"


def parse_check_args(args: List[str], is_fmt: bool = False) -> CheckOptions:
    opt = CheckOptions(fix=is_fmt)
    i=0
    while i < len(args):
        a=args[i]
        if a in ("-h", "--help"):
            print(FMT_HELP if is_fmt else CHECK_HELP); raise SystemExit(0)
        elif a in ("-f", "--fix"):
            opt.fix=True
        elif a == "--diff": opt.diff=True
        elif a == "--check": opt.check=True
        elif a in ("-l", "--list-rules"): opt.list_rules=True
        elif a in ("-d", "--disable"):
            i+=1; opt.disable += split_rules(args[i])
        elif a in ("-e", "--enable", "--rules"):
            i+=1; opt.enable += split_rules(args[i])
        elif a == "--extend-enable": i+=1; opt.extend_enable += split_rules(args[i])
        elif a == "--extend-disable": i+=1; opt.extend_disable += split_rules(args[i])
        elif a == "--exclude": i+=1; opt.exclude += split_patterns(args[i])
        elif a == "--include": i+=1; opt.include += split_patterns(args[i])
        elif a == "--no-exclude": opt.no_exclude=True
        elif a.startswith("--respect-gitignore"):
            if a == "--respect-gitignore":
                if i+1 < len(args) and args[i+1] in ("true","false"):
                    i+=1; opt.respect_gitignore=(args[i].lower()=="true")
                else: opt.respect_gitignore=True
            elif "=" in a:
                opt.respect_gitignore = a.split("=",1)[1].lower()=="true"
        elif a in ("-v", "--verbose"): opt.verbose=True
        elif a == "--profile": opt.profile=True
        elif a == "--statistics": opt.statistics=True
        elif a in ("--config", "-c"):
            i+=1; opt.config=args[i]
        elif a in ("--no-config", "--isolated"):
            opt.no_config=True
        elif a in ("-q", "--quiet"): opt.quiet=True
        elif a in ("-s", "--silent"): opt.silent=True
        elif a in ("-o", "--output", "--output-format"):
            i+=1; opt.output_format=args[i]
        elif a == "--show-full-path": opt.show_full_path=True
        elif a == "--flavor": i+=1; opt.flavor=args[i]
        elif a == "--stdin": opt.stdin=True
        elif a == "--stdin-filename": i+=1; opt.stdin_filename=args[i]
        elif a == "--stderr": opt.stderr=True
        elif a in ("-w", "--watch"): pass
        elif a == "--force-exclude": opt.force_exclude=True
        elif a == "--no-cache": opt.no_cache=True
        elif a == "--cache-dir": i+=1; opt.cache_dir=args[i]
        elif a == "--fail-on": i+=1; opt.fail_on=args[i]
        elif a == "--color": i+=1; opt.color=args[i]
        elif a.startswith("-"):
            eprint(f"error: unexpected argument '{a}' found\n\nUsage: {PROGRAM} {'fmt' if is_fmt else 'check'} [OPTIONS] [PATHS]...\n\nFor more information, try '--help'.")
            raise SystemExit(2)
        else:
            opt.paths.append(a)
        i+=1
    if not opt.paths and not opt.stdin:
        opt.paths=["."]
    if "-" in opt.paths:
        opt.stdin=True
    if not opt.output_format:
        opt.output_format = os.environ.get("RUMDL_OUTPUT_FORMAT", "text")
    return opt


def command_check(args: List[str], is_fmt: bool=False) -> int:
    start=time.time()
    try:
        opt=parse_check_args(args, is_fmt)
    except SystemExit as ex:
        return int(ex.code)
    if opt.list_rules:
        return command_rule([])
    try:
        loaded=load_config(opt.config, opt.no_config)
    except FileNotFoundError as ex:
        eprint(f"Error: {ex}"); return 2
    except Exception as ex:
        eprint(f"Error: {ex}"); return 2
    cfg=loaded.data
    if opt.no_exclude:
        cfg["_no_exclude"] = True
    if opt.flavor:
        cfg.setdefault("global", {})["flavor"] = opt.flavor
    respect = opt.respect_gitignore if opt.respect_gitignore is not None else bool(cfg.get("global", {}).get("respect-gitignore", True))
    rules=selected_rules(cfg,opt.enable,opt.disable,opt.extend_enable,opt.extend_disable)
    if opt.verbose and not opt.silent:
        print("Enabled rules:")
        for r in RULES:
            if r["code"] in rules:
                print(f"  - {r['code']} ({r['summary']})")
    all_issues: List[Issue]=[]
    nfiles=0
    files_data: List[Tuple[str, Optional[Path], str]]=[]
    stdin_mode=opt.stdin or opt.paths==["-"]
    if stdin_mode:
        data=sys.stdin.read()
        name=opt.stdin_filename or "<stdin>"
        files_data.append((name,None,data)); nfiles=1
    else:
        try:
            files=collect_files(opt.paths,cfg,opt.include,opt.exclude,respect,opt.force_exclude)
        except FileNotFoundError as ex:
            eprint(f"Error: {ex}"); return 2
        for p in files:
            try:
                data=p.read_text(encoding="utf-8", errors="replace")
            except Exception as ex:
                eprint(f"Error reading {p}: {ex}"); return 2
            disp=str(p.resolve() if opt.show_full_path else p)
            files_data.append((disp,p,data))
        nfiles=len(files_data)
    fixed_outputs: Dict[str,str]={}
    any_changed=False
    for disp,p,data in files_data:
        per_rules=apply_per_file_ignores(rules, disp, cfg)
        base=(p.parent if p else Path.cwd())
        issues=lint_text(data, disp, cfg, per_rules, base)
        # If fixing/diff/check, compute formatted output and mark fixable issues as fixed if text changed.
        if opt.fix or is_fmt or opt.diff or opt.check:
            fixed=fix_text(data,cfg,per_rules)
            fixed_outputs[disp]=fixed
            if fixed != data:
                any_changed=True
                for x in issues:
                    if x.fixable:
                        x.fixed = bool(opt.fix or is_fmt)
            if (opt.fix or is_fmt) and p is not None and fixed != data:
                p.write_text(fixed, encoding="utf-8")
        all_issues.extend(issues)
    elapsed=max(0,int((time.time()-start)*1000))
    stream=sys.stderr if opt.stderr else sys.stdout
    # Stdin formatter mode: emit fixed content only.
    if stdin_mode and (opt.fix or is_fmt):
        disp=files_data[0][0]
        sys.stdout.write(fixed_outputs.get(disp, fix_text(files_data[0][2], cfg, rules)))
        return 0
    if opt.diff:
        for disp,p,data in files_data:
            fixed=fixed_outputs.get(disp,data)
            if fixed != data:
                diff=list(difflib.unified_diff(data.splitlines(), fixed.splitlines(), fromfile=disp, tofile=f"{disp} (fixed)", lineterm=""))
                # Observed output repeats per fixable issue; one unified diff is more useful.
                for line in diff:
                    print(line, file=stream)
        if all_issues and not opt.quiet and not opt.silent:
            print("", file=stream)
            print(summary_line(len(all_issues), nfiles, elapsed), file=stream)
            fx=sum(1 for x in all_issues if x.fixable)
            if fx: print(f"Run `rumdl fmt` to automatically fix {fx} of the {len(all_issues)} issues", file=stream)
    else:
        fixed_count = None
        if opt.fix or is_fmt:
            fixed_count=sum(1 for x in all_issues if x.fixable and x.fixed)
        output_issues(all_issues,nfiles,opt.output_format,elapsed,opt.quiet,opt.silent,fixed_count,True,stream,opt.statistics)
        if opt.profile and not opt.silent and opt.output_format not in ("json","gitlab","sarif","junit"):
            print("", file=stream); print("Profiling is disabled.", file=stream)
    if is_fmt:
        return 0
    if opt.fail_on == "never":
        return 0
    if opt.check and any_changed:
        return 1
    if not all_issues:
        return 0
    if opt.fail_on == "error":
        return 1 if any(x.severity == "error" for x in all_issues) else 0
    if opt.fail_on == "warning":
        return 1 if any(x.severity in ("warning","error") for x in all_issues) else 0
    return 1


