        elif a=="--format": i+=1; fmt=args[i]
        elif a=="--dry-run": dry=True
        elif a in ("--color","--config"): i+=1
        elif a in ("--no-config","--isolated"): pass
        elif not a.startswith("-") and file is None: file=a
        i+=1
    if not file: eprint("Import error: missing input file"); return 2
    try:
        text=Path(file).read_text()
    except Exception as ex:
        eprint(f"Import error: Failed to read config file {file}: {ex}"); return 2
    try:
        data=json.loads(text)
    except Exception:
        # Tiny YAML subset: key: value/object.
        data={}
        for line in text.splitlines():
            line=line.strip()
            if not line or line.startswith("#"): continue
            if ":" in line:
                k,v=line.split(":",1); v=v.strip()
                if v.lower() in ("true","false"): data[k.strip()]=v.lower()=="true"
                elif v.startswith("["): 
                    try: data[k.strip()]=json.loads(v)
                    except Exception: data[k.strip()]=v
                else: data[k.strip()]=v.strip('"\'')
    cfg={"global":{"disable":[]}}
    for k,v in data.items():
        code=normalize_rule_id(k)
        if k.lower()=="default":
            continue
        if not code: continue
        if v is False:
            cfg["global"].setdefault("disable",[]).append(code)
        elif isinstance(v,dict):
            cfg[code]={normalize_key(kk):vv for kk,vv in v.items() if kk not in ("enabled",)}
    if not cfg["global"].get("disable"):
        cfg.pop("global",None)
    textout=json.dumps(cfg,indent=2) if fmt=="json" else config_to_toml(cfg)
    if dry:
        print(textout, end="" if textout.endswith("\n") else "\n")
    else:
        Path(outfile).write_text(textout); print(f"Imported configuration written to {outfile}")
    return 0


